import { PUBLIC_API_URL, PUBLIC_API_KEY } from '$env/static/public';

/**
 * Files generated by the Butterfly public API (sitemap and txt-files
 * plugins): `/v1/sitemaps/{file}` and `/v1/txt-files/{file}`. They are not
 * JSON:API, so the raw response is relayed instead of going through the
 * client of `$lib/api`.
 */

const base = PUBLIC_API_URL.replace(/\/+$/, '');

export type ApiFile = {
  status: number;
  body: string;
  contentType: string | null;
  maxAge: number | null;
};

/** Past it, the API counts as unreachable (robots.txt then serves its fallback). */
const TIMEOUT_MS = 3000;

/** GET a generated file. A network error or a timeout comes back as a 502. */
export async function getApiFile(fetch: typeof globalThis.fetch, path: string): Promise<ApiFile> {
  try {
    const res = await fetch(`${base}${path}`, {
      headers: { 'X-Butterfly-Key': PUBLIC_API_KEY },
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    const maxAge = /max-age=(\d+)/.exec(res.headers.get('cache-control') || '');
    return {
      status: res.status,
      body: await res.text(),
      contentType: res.headers.get('content-type'),
      maxAge: maxAge ? Number(maxAge[1]) : null,
    };
  } catch {
    return { status: 502, body: '', contentType: null, maxAge: null };
  }
}

/** `public, max-age=N` with the stale-while-revalidate of `$lib/cacheControl` (an hour at most). */
export const cacheFor = (seconds: number) =>
  `public, max-age=${seconds}, stale-while-revalidate=${Math.min(seconds, 3600)}`;
